/**
 * One cell of a worksheet: a discriminated union on `type` whose typed value is `value`
 * (none for `Blank`). `text` is the display text, `raw` the stored spelling (the serial for
 * dates), `format` the code that produced `text`, `formula` the expression stored on this
 * cell, `sharedFormula` the master cell when this cell follows a shared formula, `cached`
 * whether a result was stored, `merge` the range this cell anchors, `hidden` whether its row
 * or column is hidden, `box` its rectangle in the sheet frame (a merged anchor spans its
 * range).
 */
export type SheetCell =
  | {
      type: "Text";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
      value: string;
    }
  | {
      type: "Number";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
      value: number;
    }
  | {
      type: "Boolean";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
      value: boolean;
    }
  | {
      type: "Error";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
      value: string;
    }
  | {
      type: "Date";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
      value: string;
    }
  | {
      type: "Blank";
      ref: string;
      row: number;
      col: number;
      text: string;
      raw: string;
      format?: string;
      formatSupported: boolean;
      formula?: string;
      sharedFormula?: string;
      cached: boolean;
      merge?: string;
      hidden: boolean;
      box: CellBox;
    };

/** One selected worksheet's cells, with the sheet facts a reader needs beside them. */
export interface SheetCells {
  sheet: string;
  /** Position in the workbook, 0-based. */
  index: number;
  hidden: boolean;
  /** The declared `<dimension>`, which a producer may overstate. */
  dimension?: string;
  printArea?: string;
  /** Merged ranges in A1 form. */
  merges: Array<string>;
  /**
   * The sheet frame's size in points: A1 to the last non-empty cell or merged range, with hidden
   * rows and columns counted or not per `hiddenCells`.
   */
  width: number;
  height: number;
  /** Points; what a column or row absent from `columns` / `rows` measures. */
  defaultColumnWidth: number;
  defaultRowHeight: number;
  /** Only the columns and rows that differ from the default or are hidden. */
  columns: Array<SheetColumn>;
  rows: Array<SheetRow>;
  warnings: Array<string>;
  cells: Array<SheetCell>;
}

/** A column whose width differs from the sheet default, or that is hidden. 0-based. */
export interface SheetColumn {
  index: number;
  /** Points; zero for a hidden column when hidden cells are excluded. */
  width: number;
  hidden: boolean;
}

/**
 * A row whose height differs from the sheet default (auto-fit growth included), or that is
 * hidden. 0-based.
 */
export interface SheetRow {
  index: number;
  /** Points; zero for a hidden row when hidden cells are excluded. */
  height: number;
  hidden: boolean;
}

/** The cells of a workbook buffer's selected sheets. */
export declare function spreadsheetCells(
  buffer: Buffer,
  opts?: SpreadsheetOptions | undefined | null
): Array<SheetCells>;

export declare function spreadsheetCellsAsync(
  buffer: Buffer,
  opts?: SpreadsheetOptions | undefined | null
): Promise<Array<SheetCells>>;

/** Workbook options shared by `spreadsheetCells` and `layout`. */
export interface SpreadsheetOptions {
  /** Sheet names to include, in workbook order; default: every visible sheet. */
  sheets?: Array<string>;
  /** Include hidden sheets (default false). */
  hiddenSheets?: boolean;
  /**
   * Cells in hidden rows and columns. For `spreadsheetCells` the default is true: they are listed
   * with `hidden: true`. For `layout` the default is false: zero extent and omitted; true gives
   * them their real extents back.
   */
  hiddenCells?: boolean;
}

export interface StringField {
  value: string;
  /** The exact source text the value was derived from. */
  text: string;
  confidence: number;
  span?: FieldSpan;
}

export interface StructuredPageText {
  page: number;
  header: string;
  body: string;
  footer: string;
}

export interface TaxDetail {
  rate?: NumberField;
  amount?: MoneyField;
  base?: MoneyField;
  category?: StringField;
}

/**
 * Words sharing a baseline band, left to right. `firstWord` / `wordCount`
 * address a contiguous slice of `PageLayout.words`.
 */
export interface TextLine {
  text: string;
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  firstWord: number;
  wordCount: number;
}

/**
 * The deepest tier of the OCR cascade that ran for a page: `Native` when the
 * page's own glyphs were the page, `Ocr` when its embedded rasters were OCR'd,
 * `Rendered` when the page was rasterised and OCR'd (only with the `render`
 * feature). A hybrid page keeps its native words alongside the OCR words and
 * still reports the OCR tier, even when that tier added no words; tell the
 * two apart by `confidence`, which only OCR words carry, and see the "native
 * words kept" warnings. `Spreadsheet` is the logical page of a workbook sheet,
 * laid out from column widths and row heights. Present in every build.
 */
export type TextSource = "Native" | "Ocr" | "Rendered" | "Spreadsheet";

/** One word with its box in PDF user space (points, y up). */
export interface TextWord {
  text: string;
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  /** Index into `PageLayout.lines`. */
  line: number;
  /** Native only: font size in user space (after the CTM), in points. */
  fontSize?: number;
  /** Native only: base font name with any subset prefix stripped. */
  fontName?: string;
  /**
   * Native: from the font descriptor and name; absent when the font gives no weight evidence
   * (anonymous names such as `CIDFont+F1`) and for OCR words.
   */
  bold?: boolean;
  italic?: boolean;
  /** Native only: true when the word is set in a barcode font, so its glyphs are bars, not letters. */
  symbolic?: boolean;
  /** OCR only: Tesseract word confidence, 0..1. */
  confidence?: number;
  /**
   * Spreadsheet only: the reference of the cell this word was laid out from (`"C3"`); the
   * anchor for a merged range.
   */
  cell?: string;
}

/**
 * A logical field with no widget placed on any page. Keeps the full field payload; only
 * geometry and per-widget state are absent.
 */
export interface UnplacedFormField {
  /**
   * `"N G obj"`, or `"<parent fieldObjectId>/kid I"` / `"/Fields I"` when the field
   * dictionary itself is written inline.
   */
  fieldObjectId: string;
  name: string;
  partialName: string;
  type: FormFieldType;
  value?: string;
  /** Multi-select list boxes. */
  values?: Array<string>;
  defaultValue?: string;
  tooltip?: string;
  mappingName?: string;
  /** Choice fields. */
  options?: Array<ChoiceOption>;
  maxLen?: number;
  readOnly: boolean;
  required: boolean;
  noExport: boolean;
  hasActions: boolean;
  multiline: boolean;
  password: boolean;
  comb: boolean;
  richText: boolean;
  editable: boolean;
  multiSelect: boolean;
  /** Signature fields: signature data present in /V (not cryptographic validation). */
  signed: boolean;
}
